"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[2676],{4705(e){e.exports=JSON.parse('{"tag":{"label":"Branch and Bound","permalink":"/concepts/tags/branch-and-bound","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"state-space-search-and-optimization/branch-and-bound","title":"Branch and Bound","description":"Branch and bound (B&B) is the last design technique of the course. Like backtracking, it searches an implicit tree of states: nodes represent states of the problem, edges represent valid changes, and solving the problem means finding a node (or a path) in that tree. The difference is the order in which the tree is explored, and that single change makes it suitable for different problems.","permalink":"/concepts/state-space-search-and-optimization/branch-and-bound"},{"id":"state-space-search-and-optimization/branch-and-bound-examples","title":"Branch and Bound: Classic Problems","description":"This lesson applies the general scheme of branch and bound to several problems. In each one, the work consists of answering the same three questions:","permalink":"/concepts/state-space-search-and-optimization/branch-and-bound-examples"},{"id":"state-space-search-and-optimization/exercises","title":"Exercises: Backtracking and Branch and Bound","description":"These exercises review the four lessons of the chapter. They are different from the seminar activities (paths, Hamiltonian cycles and the traveling salesman) and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/state-space-search-and-optimization/exercises"}],"unlisted":false}}')}}]);